/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `mkbs_set_nosology_before_insert` BEFORE INSERT ON `mkbs` FOR EACH ROW SET NEW.nosology_id = (
    SELECT id
    FROM nosologies n
    WHERE LEFT(NEW.code, 3) BETWEEN LEFT(SUBSTRING_INDEX(n.code, '-', 1), 3)
                                AND LEFT(SUBSTRING_INDEX(n.code, '-', -1), 3)
    LIMIT 1
) */;;
